import type { L10n } from "@/lib/i18n";
import manifest from "./photo-manifest.json";

/**
 * Photos used on the site. Files are generated by `npm run images` from
 * photos-src/<key>.jpg. All current photos are from Unsplash and free to use
 * under the Unsplash License (https://unsplash.com/license) – credit is not
 * required, but we give it on the About page.
 */
export type PhotoKey = keyof typeof manifest;

export interface PhotoInfo {
  key: PhotoKey;
  alt: L10n;
  /** CSS object-position, used when the photo is cropped. */
  position?: string;
  credit: { name: string; url: string };
}

const unsplash = (name: string, path: string) => ({ name, url: `https://unsplash.com/photos/${path}` });

